  Widget _buildUploadButton(VersionDoc? currentVersion, String? rolDocumental) {
    return TextButton.icon(
      onPressed: currentVersion == null
          ? null
          : () async {
              await _pickAndUploadPdf(currentVersion, rolDocumental);
            },
      icon: const Icon(Icons.upload_file, size: 16),
      label: const Text(
        'Subir PDF',
        style: TextStyle(fontFamily: kArial, fontWeight: FontWeight.w800),
      ),
    );
  }

  Future<void> _pickAndUploadPdf(VersionDoc currentVersion, String? rolDocumental) async {
    final result = await FilePicker.platform.pickFiles(
      type: FileType.custom,
      allowedExtensions: ['pdf'],
      withData: true, // Necesario para obtener los bytes directamente
    );

    if (result != null && result.files.single.bytes != null && result.files.single.path != null) {
      final file = result.files.single;
      final bytes = file.bytes!;
      final nombre = file.name;

      await _handleAction(() => _service.subirPdf(
            docId: widget.docId,
            versionId: currentVersion.versionId,
            empresaId: widget.empresaId,
            numeroVersion: currentVersion.numero,
            bytes: bytes,
            nombre: nombre,
            actorId: widget.userId,
            rolDocumental: rolDocumental!,
            nombreActor: getUserName(null), // Asumiendo que el nombre del actor se obtiene de alguna forma
          ));
    } else {
       ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('No se seleccionó ningún archivo o hubo un error al obtener los bytes.')));
    }
  }

  Widget _buildWatermarkOverlay(GdEstado estado) {
    if (estado == GdEstado.vigente) return const SizedBox.shrink();
    return IgnorePointer(
      child: Center(
        child: RotationTransition(
          turns: const AlwaysStoppedAnimation(-45 / 360),
          child: Text(
            estado.etiqueta.toUpperCase(),
            style: TextStyle(
              fontFamily: kArial,
              fontSize: 60,
              fontWeight: FontWeight.w900,
              color: Colors.black.withOpacity(0.05),
              letterSpacing: 10,
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildActionsTab(
    DocumentoDoc doc,
    VersionDoc? currentVersion,
    String? rolDocumental,
  ) {
    final currentVersionId = currentVersion?.versionId;
    final puedeEnviar = currentVersionId != null && GdRoles.puedeEjecutar('enviar_revision', rolDocumental);
    final puedeObservar = currentVersionId != null && GdRoles.puedeEjecutar('observar', rolDocumental);
    final puedeReenviar = currentVersionId != null && GdRoles.puedeEjecutar('reenviar', rolDocumental);
    final puedeAprobar = currentVersionId != null && GdRoles.puedeEjecutar('aprobar', rolDocumental);
    final puedeFirmar = currentVersionId != null && GdRoles.puedeEjecutar('firmar', rolDocumental);
    final puedeMarcarVigente = currentVersionId != null && GdRoles.puedeEjecutar('marcar_vigente', rolDocumental);
    final puedeNuevaVersion = GdRoles.puedeEjecutar('nueva_version', rolDocumental);

    return ListView(
      padding: const EdgeInsets.all(24),
      children: [
        const Text(
          'Flujo de Aprobacion',
          style: TextStyle(
            fontFamily: kArial,
            fontWeight: FontWeight.w900,
            fontSize: 16,
            color: GdPalette.primary,
          ),
        ),
        const SizedBox(height: 20),
        if (doc.estado == GdEstado.borrador && puedeEnviar)
          _buildActionButton(
            label: 'ENVIAR A REVISION',
            icon: Icons.send,
            onPressed: () => _handleAction(
              () => _service.enviarARevision(
                docId: doc.docId,
                versionId: currentVersionId!,
                empresaId: widget.empresaId,
                actorId: widget.userId,
                rolDocumental: rolDocumental!,
                nombreActor: getUserName(null),
              ),
            ),
          ),
        if (doc.estado == GdEstado.en_revision && puedeAprobar)
          _buildActionButton(
            label: 'APROBAR FORMALMENTE',
            icon: Icons.verified,
            color: GdPalette.success,
            onPressed: () => _handleAction(
              () => _service.aprobar(
                docId: doc.docId,
                versionId: currentVersionId!,
                empresaId: widget.empresaId,
                actorId: widget.userId,
                rolDocumental: rolDocumental!,
                nombreActor: getUserName(null),
              ),
            ),
          ),
        if (doc.estado == GdEstado.en_revision && puedeAprobar && puedeObservar)
          const SizedBox(height: 12),
        if (doc.estado == GdEstado.en_revision && puedeObservar)
          _buildActionButton(
            label: 'OBSERVAR / RECHAZAR',
            icon: Icons.rule,
            color: GdPalette.warning,
            onPressed: () =>
                _showObservationDialog(doc, currentVersionId!, rolDocumental!),
          ),
        if (doc.estado == GdEstado.observado && puedeReenviar)
          _buildActionButton(
            label: 'REENVIAR A REVISION',
            icon: Icons.refresh,
            onPressed: () => _handleAction(
              () => _service.reenviar(
                docId: doc.docId,
                versionId: currentVersionId!,
                empresaId: widget.empresaId,
                actorId: widget.userId,
                rolDocumental: rolDocumental!,
                nombreActor: getUserName(null),
              ),
            ),
          ),
        if (doc.estado == GdEstado.aprobado && puedeFirmar)
          _buildActionButton(
            label: 'FIRMAR INTERNAMENTE',
            icon: Icons.draw,
            color: GdPalette.success,
            onPressed: () => _handleAction(
              () => _service.firmar(
                docId: doc.docId,
                versionId: currentVersionId!,
                empresaId: widget.empresaId,
                actorId: widget.userId,
                rolDocumental: rolDocumental!,
                nombreActor: getUserName(null),
              ),
            ),
          ),
        if (doc.estado == GdEstado.firmado && puedeMarcarVigente)
          _buildActionButton(
            label: 'MARCAR COMO VIGENTE',
            icon: Icons.public,
            color: GdPalette.primary,
            onPressed: () => _handleAction(
              () => _service.marcarVigente(
                docId: doc.docId,
                versionId: currentVersionId!,
                empresaId: widget.empresaId,
                actorId: widget.userId,
                rolDocumental: rolDocumental!,
                nombreActor: getUserName(null),
              ),
            ),
          ),
        if (doc.estado == GdEstado.vigente && puedeNuevaVersion)
          _buildActionButton(
            label: 'INICIAR NUEVA VERSION',
            icon: Icons.add_to_photos,
            onPressed: () => _handleAction(
              () => _service.iniciarNuevaVersion(
                docId: doc.docId,
                empresaId: widget.empresaId,
                actorId: widget.userId,
                rolDocumental: rolDocumental!,
                nombreActor: getUserName(null),
              ),
            ),
          ),
        if (rolDocumental == null)
          ...
          (rolDocumental == null
              ? [
                  const SizedBox(height: 16),
                  const Text(
                    'El usuario actual no tiene rol documental configurado para esta empresa.',
                    style: TextStyle(fontFamily: kArial, color: GdPalette.error),
                  )
                ]
              : []),
        const SizedBox(height: 40),
        _buildHelpCard(),
      ],
    );
  }

  Widget _buildActionButton({
    required String label,
    required IconData icon,
    required VoidCallback onPressed,
    Color? color,
  }) {
    return ElevatedButton.icon(
      onPressed: _loadingAction ? null : onPressed,
      icon: Icon(icon, size: 20),
      label: Text(
        label,
        style: const TextStyle(
          fontFamily: kArial,
          fontWeight: FontWeight.w900,
          fontSize: 13,
        ),
      ),
      style: ElevatedButton.styleFrom(
        backgroundColor: color ?? GdPalette.accent,
        foregroundColor: Colors.white,
        padding: const EdgeInsets.symmetric(vertical: 20),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
      ),
    );
  }

  Widget _buildHelpCard() {
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: GdPalette.background,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: GdPalette.border),
      ),
      child: const Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'Ayuda de Proceso',
            style: TextStyle(
              fontFamily: kArial,
              fontWeight: FontWeight.w800,
              fontSize: 14,
            ),
          ),
          SizedBox(height: 8),
          Text(
            'Para que un documento sea Vigente, debe pasar por Revision, Aprobacion y Firma. El sistema genera un historial inalterable de cada paso.',
            style: TextStyle(
              fontFamily: kArial,
              fontSize: 12,
              color: GdPalette.muted,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildVersionsTab(List<VersionDoc> versions) {
    if (versions.isEmpty) {
      return const Center(
        child: Text(
          'Sin versiones registradas.',
          style: TextStyle(fontFamily: kArial, color: GdPalette.muted),
        ),
      );
    }

    return ListView.separated(
      padding: const EdgeInsets.all(24),
      itemCount: versions.length,
      separatorBuilder: (_, __) => const SizedBox(height: 12),
      itemBuilder: (_, i) {
        final v = versions[i];
        return GdCard(
          padding: const EdgeInsets.all(12),
          border: Border.all(
            color: v.esVigente ? GdPalette.primary : GdPalette.border,
            width: v.esVigente ? 2 : 1,
          ),
          child: Row(
            children: [
              Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    v.etiqueta,
                    style: const TextStyle(
                      fontFamily: kArial,
                      fontWeight: FontWeight.w900,
                      fontSize: 16,
                    ),
                  ),
                  Text(
                    v.subidoEn != null
                        ? DateFormat('dd/MM/yyyy').format(v.subidoEn!.toDate())
                        : '-',
                    style: const TextStyle(
                      fontFamily: kArial,
                      fontSize: 11,
                      color: GdPalette.muted,
                    ),
                  ),
                ],
              ),
              const Spacer(),
              GdStatusBadge(estado: v.estado, isVigente: v.esVigente),
            ],
          ),
        );
      },
    );
  }

  Widget _buildHistoryTab(DocumentoDoc doc) {
    return StreamBuilder<List<FlujoEventoDoc>>(
      stream: _service.streamHistorial(doc.docId),
      builder: (context, snapshot) {
        if (!snapshot.hasData) {
          return const Center(child: CircularProgressIndicator());
        }
        final events = snapshot.data!;
        return ListView.builder(
          padding: const EdgeInsets.all(24),
          itemCount: events.length,
          itemBuilder: (_, i) {
            final e = events[i];
            return GdTimelineItem(
              title: GdAccionX.deString(e.accion).descripcion,
              actor: e.nombreActor ?? e.realizadoPor,
              date: e.realizadoEn != null
                  ? DateFormat('dd/MM/yyyy HH:mm').format(e.realizadoEn!.toDate())
                  : '-',
              comment: e.observacion,
              isFirst: i == 0,
              isLast: i == events.length - 1,
              accion: GdAccionX.deString(e.accion),
            );
          },
        );
      },
    );
  }

  Future<void> _handleAction(Future<void> Function() action) async {
    setState(() => _loadingAction = true);
    try {
      await action();
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context)
            .showSnackBar(SnackBar(content: Text('Error: $e')));
      }
    } finally {
      if (mounted) setState(() => _loadingAction = false);
    }
  }

  void _showObservationDialog(
    DocumentoDoc doc,
    String versionId,
    String rolDocumental,
  ) {
    final controller = TextEditingController();
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text(
          'Observaciones / Rechazo',
          style: TextStyle(fontFamily: kArial, fontWeight: FontWeight.w900),
        ),
        content: TextField(
          controller: controller,
          maxLines: 4,
          decoration: const InputDecoration(
            hintText: 'Escriba el motivo del rechazo u observaciones...', 
            border: OutlineInputBorder(),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancelar'),
          ),
          ElevatedButton(
            onPressed: () {
              final obs = controller.text.trim();
              if (obs.isEmpty) return;
              Navigator.pop(context);
              _handleAction(
                () => _service.observar(
                  docId: doc.docId,
                  versionId: versionId,
                  empresaId: widget.empresaId,
                  actorId: widget.userId,
                  rolDocumental: rolDocumental,
                  observacion: obs,
                ),
              );
            },
            style: ElevatedButton.styleFrom(backgroundColor: GdPalette.error),
            child: const Text('Enviar Observaciones'),
          ),
        ],
      ),
    );
  }

  Future<void> _launchURL(String url) async {
    if (!await launchUrl(Uri.parse(url))) {
      throw Exception('Could not launch $url');
    }
  }
}

